        diffArrive("LEG1", 3, List.of("BAG1")).andExpect(status().isOk());
        // 之后不能再执行另一种到达确认（精确）
        arriveExact("LEG1", List.of("BAG1", "BAG2")).andExpect(status().isUnprocessableEntity());
        // 也不能重复差异到达
        diffArrive("LEG1", 4, List.of("BAG1")).andExpect(status().isUnprocessableEntity());

