            .andExpect(jsonPath("$.proof[0].side").value("RIGHT"))
            .andExpect(jsonPath("$.proof[0].digest").value(leafHex("BAG-C")))
            .andExpect(jsonPath("$.proof[1].side").value("LEFT"))
            .andExpect(jsonPath("$.proof[1].digest")
